using System.Reflection;
using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    // Technical namespaces the business layers must not touch.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Text.Json", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
        "Microsoft.Extensions", "Microsoft.AspNetCore", "Newtonsoft",
    ];

    private static Assembly Load(string name) => Assembly.Load(name);

    private static void AssertNoDependencies(string assembly, params string[] forbidden)
    {
        var result = Types.InAssembly(Load(assembly))
            .ShouldNot().HaveDependencyOnAny(forbidden)
            .GetResult();

        Assert.True(result.IsSuccessful,
            $"{assembly} must not depend on [{string.Join(", ", forbidden)}]. Offenders: " +
            string.Join(", ", result.FailingTypeNames ?? []));
    }

    [Fact]
    public void Domain_depends_on_neither_other_layers_nor_technical_details()
        => AssertNoDependencies(Domain, [Application, Infrastructure, .. TechnicalNamespaces]);

    [Fact]
    public void Application_depends_on_neither_infrastructure_nor_technical_details()
        => AssertNoDependencies(Application, [Infrastructure, .. TechnicalNamespaces]);
}
